PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR CONSTANT
    LEVEL_LOW : INT := 10;
    LEVEL_HIGH : INT := 90;
END_VAR

IF Level >= LEVEL_HIGH THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LEVEL_LOW THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

