PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

