    0: // At-bottom
        MotorUp := CallUp AND DoorClosed;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF NOT AtBottom THEN
            State := 1;
        END_IF;

    1: // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF AtTop OR NOT DoorClosed THEN
            State := 2;
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := CallDown AND DoorClosed;
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF NOT AtBottom THEN
            State := 3;
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := 0;
        END_IF;

END_CASE;

END_PROGRAM

