    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:  // At-bottom
        MotorUp := CallUp AND DoorClosed;
        MotorDown := FALSE;
        IF CallDown OR AtTop THEN
            State := 3;
        END_IF;

    1:  // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF AtTop OR NOT CallUp OR NOT DoorClosed THEN
            State := 2;
        END_IF;

    2:  // At-top
        MotorUp := FALSE;
        MotorDown := CallDown AND DoorClosed;
        IF CallUp OR AtBottom THEN
            State := 0;
        END_IF;

    3:  // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF AtBottom OR NOT CallDown OR NOT DoorClosed THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF NOT AtBottom THEN
            MotorDown := TRUE;
        ELSE
            MotorDown := FALSE;
        END_IF;

    1: // Moving-up
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF AtTop OR NOT DoorClosed THEN
            State := 2;
        END_IF;
        MotorUp := DoorClosed;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF NOT AtTop THEN
            MotorUp := TRUE;
        ELSE
            MotorUp := FALSE;
        END_IF;

    3: // Moving-down
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := 0;
        END_IF;
        MotorDown := DoorClosed;

END_CASE;

END_PROGRAM

