PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor  : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT;
    PrevEntry : BOOL;
    PrevExit : BOOL;
END_VAR
VAR CONSTANT
    CAP : INT := 3;
END_VAR

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

IF EntrySensor AND NOT PrevEntry THEN
    Count := MIN(Cap, Count + 1);
ELSIF ExitSensor AND NOT PrevExit THEN
    Count := MAX(0, Count - 1);
END_IF;

FullSign := Count >= Cap;
EntryBarrierOpen := EntryReq AND (Count < Cap);

END_PROGRAM

