    PT_STAR : TIME := T#3s;
END_VAR

CASE EStop OF
    FALSE:
        State := 0;
        StarK := FALSE;
        DeltaK := FALSE;
    TRUE:
        CASE State OF
            0, 2:
                IF StartPB AND NOT StopPB THEN
                    State := 1;
                END_IF;
            1:
                IF StopPB OR (State = 1 AND T#0s >= PT_STAR) THEN
                    State := 0;
                ELSIF EStop THEN
                    State := 0;
                END_IF;
        END_CASE;
END_CASE;

CASE State OF
    0:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
END_CASE;

END_PROGRAM

