PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF Level >= 90 AND State <> 1 THEN
    State := 1;
ELSIF Level <= 10 AND State <> 2 THEN
    State := 2;
END_IF;

CASE State OF
    0:  // Idle
        Pump := FALSE;
        Valve := FALSE;
    1:  // Filling
        Pump := TRUE;
        Valve := FALSE;
    2:  // Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

