    State := 0;
ELSIF EStop AND (State = 0) AND StartCycle AND (Level < HI) THEN
    State := 1;
ELSIF EStop AND (State = 1) AND (Level < HI) THEN
    State := 1;
ELSIF EStop AND (State = 2) AND (Level > LO) THEN
    State := 2;
END_IF;

