PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    OFF : INT := 0;
    STARTING : INT := 1;
    RUNNING : INT := 2;
END_VAR

CASE State OF
    OFF:
        IF NOT EStop OR StopPB THEN
            State := OFF;
        ELSIF StartPB AND EStop THEN
            State := STARTING;
        END_IF;
    STARTING:
        IF NOT EStop OR StopPB THEN
            State := OFF;
        ELSIF EStop AND State = STARTING AND Ticks >= PT_SEQ THEN
            State := RUNNING;
        END_IF;
    RUNNING:
        IF NOT EStop OR StopPB THEN
            State := OFF;
        END_IF;
END_CASE;

C1 := (State >= RUNNING);
C2 := (State >= STARTING);

END_PROGRAM

