PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
    Flame   : BOOL;
END_VAR
VAR_OUTPUT
    Fan     : BOOL;
    Fuel    : BOOL;
    Ignition: BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop AND StartPB THEN
            State := 1;
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1: // Purge
        IF (NOT EStop) OR StopPB OR (TickCount >= PT_PURGE) THEN
            State := 0;
        ELSIF EStop AND (TickCount < PT_PURGE) THEN
            State := 1;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition
        IF (NOT EStop) OR StopPB OR (TickCount >= PT_IGN) THEN
            State := 0;
        ELSIF EStop AND (TickCount < PT_IGN) AND Flame THEN
            State := 3;
        ELSIF EStop AND (TickCount < PT_IGN) AND (NOT Flame) THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF EStop AND Flame THEN
            State := 3;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
    Flame   : BOOL;
END_VAR
VAR_OUTPUT
    Fan     : BOOL;
    Fuel    : BOOL;
    Ignition: BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop AND StartPB THEN
            State := 1;
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1: // Purge
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF EStop AND NOT Timer[1].Q AND Timer[1].TimeReached(PT_PURGE) THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        Timer[1].IN := EStop AND NOT StopPB;

    2: // Ignition
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF EStop AND Timer[2].Q AND Timer[2].TimeReached(PT_IGN) THEN
            State := 3;
        END_IF;
        Fan := TRUE;
        Fuel := Flame;
        Ignition := Flame;
        Timer[2].IN := EStop AND NOT StopPB;

    3: // Run
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := Flame;
        Ignition := FALSE;
