            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF (NOT EStop) OR StopPB OR (NOT EStop AND Not Flame AND State = 3) THEN
            State := 0;
        ELSIF EStop AND NOT StopPB AND NOT StartPB AND Flame AND State = 3 THEN
            State := 3;
        END_IF;
